import{_ as e,c as t,o as p,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"震下坤上 復：","description":"京氏易傳 - 震下坤上 復：","frontmatter":{"title":"震下坤上 復：","description":"京氏易傳 - 震下坤上 復："},"headers":[],"relativePath":"classics/jingshi/035.md","filePath":"classics/jingshi/035.md"}'),i={name:"classics/jingshi/035.md"};function r(n,a,c,_,o,l){return p(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="震下坤上-復" tabindex="-1">震下坤上 復： <a class="header-anchor" href="#震下坤上-復" aria-label="Permalink to “震下坤上 復：”">​</a></h1><p>陰極則反，陽道行【一作正】也。《易》雲：“君子道長，小人道消”。又曰：“七日來複”。【七日，陽之稱也。七</p><p>九稱陽之數也。謂坤上六，陰極陽戰之地，陰雖不能勝陽，然正當盛，陽不可輕犯。六陽涉六陰反下，七爻在初，故稱七日。</p><p>日亦陽也。】六爻反覆之稱。【注在前。】《易》雲：“初九，不遠復，無祗悔”。【反至初九，陽來陰復，去遠也。】（虎易注：此字因為模糊，無法辨認，我是根據“不遠復”之意，暫時一用，待以後有機會再確定。）六爻盛，卦之體總稱也。</p><p>曰一陽為一卦之主，與震為飛伏。【庚子水，乙未土。】初九元士之世，六四諸侯見應。</p><p>建始乙未至庚子，【大暑大雪見候，起坤，六月至十一月，戊子為正朔，見覆之兆。】積算起庚子至己亥，【積算起庚</p><p>子至己亥，十月至十一月，年亦然。】週而復始。土水見候。</p><p>五星從位起歲星，【歲星木星入復卦，合水土，配吉凶。】張宿從位降庚子，【二十八宿分張宿，入復卦庚子水上。】</p><p>分氣候二十八。【積算起數二十八，定吉凶六爻。】</p><p>坤上震下，動而順，是陽來蕩陰，陰柔反去，剛陽復位，君子進，小人退。《易》雲：“休復，元吉”。</p><p>陽升陰降，變六二入兌象，次併臨，二陽將進，內為悅。陰來陽去，氣漸隆，【陰不敢拒陽，奉命而已。】次降入地澤臨卦。</p>',11)])])}const h=e(i,[["render",r]]);export{f as __pageData,h as default};
